def chk(fn):
    r = fn()
    rs = list(r) if isinstance(r, tuple) else [r]
    assert all(rs), ('numeric check failed', rs)
    CNT[0] += len(rs)


def with_img(q, svg):
    q['img'] = svg
    return q


def fig_pos(f, xmax, kx, ky, xt, yt, xl, yl, dots=(), W=310, H=230, hl=()):
    return G(W, H, [(lambda t: f(t / kx) * ky, 0, xmax * kx, K.BLUE)], xt=[(kx * v, str(v)) for v in xt], yt=[(ky * v, str(v)) for v in yt],
             dots=[(kx * a, ky * b, '', 0, 0, K.RED) for a, b in dots], hl=[(ky * v, K.AMBER, True) for v in hl], xlabel=xl, ylabel=yl, pad=44)


def fig_c14():
    return fig_pos(lambda t: 100 * mp.e ** (-mp.log(2) / 5760 * t), 30000, 0.0095, 2.0, (5760, 11520, 17280, 23040, 28800), (25, 50, 75, 100), 't', '%', dots=[(5760, 50)])


def fig_time():
    return fig_pos(lambda t: 1000 * mp.e ** (0.05 * t), 10, 26.0, 0.13, (2, 4, 6, 8, 10), (1000, 1500, 1648), 't', 'A', dots=[(8.109, 1500)], hl=(1500,))


def fig_ci():
    c = lambda t: 1.26 * mp.e ** (0.009 * t)
    i = lambda t: 1.01 * mp.e ** (0.015 * t)
    kx, ky = 5.0, 90.0
    return G(310, 230, [(lambda t: c(t / kx) * ky, 0, 50 * kx, K.BLUE), (lambda t: i(t / kx) * ky, 0, 50 * kx, K.AMBER)],
             xt=[(kx * v, str(v)) for v in (10, 20, 30, 40, 50)], yt=[(ky * v, str(v).replace('.', ',')) for v in (1, 1.5, 2)],
             dots=[(kx * 36.86, ky * c(36.86), '', 0, 0, K.RED)], xlabel='t', ylabel='P', pad=44)


def fig_dep():
    return fig_pos(lambda t: 250 * 0.75 ** t, 8, 33.0, 0.8, (1, 2, 3, 4, 8), (100, 200, 250), 't', 'V', dots=[(3, 250 * 0.75 ** 3), (4, 250 * 0.75 ** 4)], hl=(100,))


