    C.append(mcq('easy', 's2', 'ក្រាបនៃ ' + M('y=\\ln x') + ' កាត់អ័ក្ស ' + M('Ox') + ' ត្រង់ចំណុចណា ?', M('(1,0)'), [M('(0,1)'), M('(e,0)'), M('(0,0)')], M('\\ln1=0') + '។', 'Remember'))
    chk(lambda: close(D(lambda t: ln(2 * t), 3), mp.mpf(1) / 3, 1e-8))
    C.append(mcq('easy', 's3', 'ដេរីវេនៃ ' + M('y=\\ln(2x)') + ' គឺ ៖', M('\\dfrac1x'), [M('\\dfrac{1}{2x}'), M('\\dfrac2x'), M('2\\ln x')], M('\\dfrac{(2x)\'}{2x}=\\dfrac2{2x}=\\dfrac1x') + '។', 'Apply'))
    chk(lambda: close(D(lambda t: t ** 3 + ln(t), 2), 12 + 0.5, 1e-8))
