    chk(lambda: (all((s + 3) * (s + 5) <= 15 for s in (mp.mpf('-2.9'), mp.mpf(-1), mp.mpf(0))), (mp.mpf('0.1') + 3) * (mp.mpf('0.1') + 5) > 15))
