    C.append(mcq('medium', 's4', 'ប្រព័ន្ធ ' + M('x+y=65') + ' , ' + M('\\ln x+\\ln y=\\ln1000') + ' មានចម្លើយ ៖', M('(25,40)') + ' និង ' + M('(40,25)'), [M('(25,40)') + ' តែមួយ', M('(5,60)') + ' និង ' + M('(60,5)'), 'គ្មានចម្លើយ'], M('\\ln x+\\ln y=\\ln(xy)') + ' ដូច្នេះ ' + M('xy=1000') + ' ; ' + M('t^2-65t+1000=0') + ' ឱ្យ ' + M('t=25,40') + '។', 'Apply'))
