    chk(lambda: all(((s * s - 4 * E ** 2 > 0) and ln(s * s - 4 * E ** 2) < 1 + ln(3 * s)) == (2 * E < s < 4 * E) for s in [mp.mpf(i) / 7 for i in range(1, 140)]))
