def cands_writing():
    C = []
    f = lambda t: t * ln(t) - t
    chk(lambda: close(D(f, 3), ln(3), 1e-8))
    # ============================================================ WRITING EASY (1)
    C.append(wr('easy', 's3', 'គណនាដេរីវេនៃ ' + M('y=x\\ln x-x') + ' រួចរកតម្លៃ ' + M('x') + ' ដែល ' + M('y\'=0') + '។',
                [('ប្រើ ' + M('(uv)\'=u\'v+uv\'') + ' ជាមួយ ' + M('u=x') + ', ' + M('v=\\ln x'), 1),
                 (M('(x\\ln x)\'=1\\cdot\\ln x+x\\cdot\\dfrac1x=\\ln x+1'), 1),
                 (M('y\'=\\ln x+1-1=\\ln x'), 1),
                 (M('y\'=0') + ' សមមូល ' + M('\\ln x=0'), 1),
                 ('ដូច្នេះ ' + M('x=e^0=1') + '។', 1)], bloom='Apply'))

    # ============================================================ WRITING MEDIUM (4)
    chk(lambda: (close(ln(5) + ln(9), ln(45), 1e-12), True))
