    # ============================================================ WRITING HARD (4)
    ph = lambda t: t - 1 - ln(t)
    chk(lambda: (ph(mp.mpf(1)) == 0 or close(ph(mp.mpf(1)), 0), all(ph(mp.mpf(s)) > 0 for s in (0.1, 0.5, 2, 5, 20))))
    C.append(wr('hard', 's5', 'ស្រាយបញ្ជាក់ថា ចំពោះគ្រប់ ' + M('x>0') + ' មាន ' + M('\\ln x\\le x-1') + ' ហើយទាញថា ' + M('\\ln x<x') + '។',
                [('តាង ' + M('\\varphi(x)=x-1-\\ln x') + ' លើ ' + M('(0,+\\infty)') + ' ; ' + M('\\varphi\'(x)=1-\\dfrac1x=\\dfrac{x-1}x'), 1),
                 (M('\\varphi\'<0') + ' ពេល ' + M('0<x<1') + ' ; ' + M('\\varphi\'>0') + ' ពេល ' + M('x>1') + ' ; ' + M('\\varphi\'(1)=0'), 1),
                 ('ដូច្នេះ ' + M('\\varphi') + ' មានអប្បបរមាត្រង់ ' + M('x=1') + ' ដែល ' + M('\\varphi(1)=1-1-0=0'), 1),
                 ('ដូច្នេះ ' + M('\\varphi(x)\\ge0') + ' គឺ ' + M('\\ln x\\le x-1') + ' គ្រប់ ' + M('x>0') + ' (សមភាពតែពេល ' + M('x=1') + ')', 1),
                 ('ដោយ ' + M('x-1<x') + ' ទាញបាន ' + M('\\ln x\\le x-1<x') + ' ដូច្នេះ ' + M('\\ln x<x') + '។', 1)], bloom='Evaluate'))
    chk(lambda: (ln(mp.pi) / mp.pi < ln(E) / E, mp.pi ** E < E ** mp.pi, close(argmax(lambda t: ln(t) / t, 0.2, 30)[0], E, 1e-5)))
    C.append(wr('hard', 's5', 'សិក្សា ' + M('f(x)=\\dfrac{\\ln x}x') + ' រួចប្រើដើម្បីប្រៀបធៀប ' + M('e^\\pi') + ' និង ' + M('\\pi^e') + '។',
                [(M('f\'(x)=\\dfrac{1-\\ln x}{x^2}') + ' មានសញ្ញាដូច ' + M('1-\\ln x'), 1),
                 (M('f\'>0') + ' លើ ' + M('(0,e)') + ' ; ' + M('f\'<0') + ' លើ ' + M('(e,+\\infty)') + ' ដូច្នេះអតិបរមា ' + M('f(e)=\\dfrac1e'), 1),
                 ('ដោយ ' + M('\\pi>e') + ' ហើយ ' + M('f') + ' ចុះលើ ' + M('(e,+\\infty)') + ' គេបាន ' + M('f(\\pi)<f(e)'), 1),
                 (M('\\dfrac{\\ln\\pi}{\\pi}<\\dfrac{\\ln e}{e}=\\dfrac1e') + ' ឱ្យ ' + M('e\\ln\\pi<\\pi'), 1),
                 ('ដូច្នេះ ' + M('\\ln(\\pi^e)<\\ln(e^\\pi)') + ' ឬ ' + M('\\pi^e<e^\\pi') + ' (ពិត ៖ ' + M('22{,}46<23{,}14') + ')។', 1)], bloom='Analyze'))
    chk(lambda: (all(ln(s) <= s / E + 1e-12 for s in [mp.mpf(i) / 10 for i in range(1, 300)]), close(argmax(lambda t: ln(t) / t, 0.2, 30)[1], 1 / E, 1e-8)))
    C.append(wr('hard', 's5', 'រកតម្លៃតូចបំផុតនៃ ' + M('a') + ' ដែលធ្វើឱ្យ ' + M('\\ln x\\le ax') + ' ចំពោះគ្រប់ ' + M('x>0') + '។ ហេតុអ្វីបានជាសមភាពកើតមានត្រង់ ' + M('x=e') + '?',
                [('ចំពោះ ' + M('x>0') + ' ៖ ' + M('\\ln x\\le ax\\Leftrightarrow\\dfrac{\\ln x}{x}\\le a'), 1),
                 ('ត្រូវការ ' + M('a\\ge\\max f') + ' ដែល ' + M('f(x)=\\dfrac{\\ln x}x'), 1),
                 (M('f\'(x)=\\dfrac{1-\\ln x}{x^2}=0') + ' ឱ្យ ' + M('x=e') + ' ; ' + M('f') + ' កើនលើ ' + M('(0,e)') + ' ចុះលើ ' + M('(e,+\\infty)'), 1),
                 ('ដូច្នេះ ' + M('\\max f=f(e)=\\dfrac1e'), 1),
                 ('ដូច្នេះ ' + M('a_{\\min}=\\dfrac1e') + ' ; សមភាព ' + M('\\ln x=\\dfrac xe') + ' កើតត្រង់ ' + M('x=e') + ' (ចំណុចដែលបន្ទាត់ ' + M('y=\\dfrac xe') + ' ប៉ះក្រាប ' + M('y=\\ln x') + ')។', 1)], bloom='Create'))
    f = lambda t: t * t * mp.sqrt(5 * t + 1) / (3 * t - 2) ** 3
    chk(lambda: close(D(f, 2) / f(2), 2 / mp.mpf(2) + 5 / (2 * (5 * 2 + 1)) - 9 / (3 * 2 - 2), 1e-8))
    g = lambda t: ((-15 * t * t - 56 * t - 8) / (2 * t * (5 * t + 1) * (3 * t - 2)))
    chk(lambda: close(D(f, 2) / f(2), g(2), 1e-8))
    C.append(wr('hard', 's3', 'ប្រើលោការីតនេពែរ រកដេរីវេនៃ ' + M('f(x)=\\dfrac{x^2\\sqrt{5x+1}}{(3x-2)^3}') + ' រួចគណនា ' + M('\\dfrac{f\'(2)}{f(2)}') + '។',
                [('យកលោការីត ៖ ' + M('\\ln f=2\\ln x+\\dfrac12\\ln(5x+1)-3\\ln(3x-2)'), 1),
                 ('ដេរីវេ ៖ ' + M('\\dfrac{f\'}{f}=\\dfrac2x+\\dfrac{5}{2(5x+1)}-\\dfrac9{3x-2}'), 1),
                 ('ដាក់ភាគបែងរួម ៖ ' + M('\\dfrac{f\'}f=\\dfrac{-15x^2-56x-8}{2x(5x+1)(3x-2)}'), 1),
                 ('ដូច្នេះ ' + M('f\'(x)=\\dfrac{-15x^2-56x-8}{2x(5x+1)(3x-2)}\\cdot\\dfrac{x^2\\sqrt{5x+1}}{(3x-2)^3}'), 1),
                 ('ត្រង់ ' + M('x=2') + ' ៖ ' + M('\\dfrac{f\'(2)}{f(2)}=\\dfrac22+\\dfrac5{22}-\\dfrac94=-\\dfrac{45}{44}') + ' (ត្រូវនឹងរូបមន្តភាគបែងរួម ' + M('\\dfrac{-180}{176}') + ')។', 1)], bloom='Create'))
    return C + cands_pisa_w()


